const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const date = '2021-10-18';
  const collectionId = 'COPERNICUS/S5P/OFFL/L3_SO2';
  const bandName = 'SO2_column_number_density';

  // Cumbre Vieja (La Palma, Canary Islands) - approximate recent eruption center
  const cumbreVieja = ee.Geometry.Point(-17.842, 28.625);
  // Funchal (Madeira Island) - capital city
  const funchal = ee.Geometry.Point(-16.908, 32.659);

  // 2. Data Acquisition & Check
  let so2Collection = ee.ImageCollection(collectionId)
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .select(bandName)
    // Filter by quality value (good practice for S5P data)
    .filter(ee.Filter.gt('quality_value', 0.75));

  const so2CollectionSize = await so2Collection.size().getInfo();

  if (so2CollectionSize === 0) {
    console.log("No Sentinel-5P SO2 images found for October 18, 2021, after quality filtering.");
    console.log("C1");
    return;
  }

  // Mosaic to get a single image for the day, if multiple exist
  const dailyImage = so2Collection.mean(); // Using mean as it's a single day. If multiple images cover same area.

  // Helper function to get SO2 concentration for a given geometry
  async function getSo2Concentration(geometry, name) {
    const scale = 1000; // Use a reasonable scale for point sampling
    const maxPixels = 1e9;

    const regionReducer = ee.Reducer.mean();
    const countReducer = ee.Reducer.count();

    // Calculate valid pixel count first
    const pixelCountResult = await dailyImage.reduceRegion({
      reducer: countReducer,
      geometry: geometry,
      scale: scale,
      maxPixels: maxPixels
    }).get(bandName).getInfo();

    if (pixelCountResult === 0) {
      console.log(`No valid pixels found for ${name} after processing.`);
      return { value: null, pixels: 0 };
    }

    // Calculate mean SO2 concentration
    const meanSo2Result = await dailyImage.reduceRegion({
      reducer: regionReducer,
      geometry: geometry,
      scale: scale,
      maxPixels: maxPixels
    }).get(bandName).getInfo();

    return { value: meanSo2Result, pixels: pixelCountResult };
  }

  // Get SO2 for Cumbre Vieja
  const cumbreViejaData = await getSo2Concentration(cumbreVieja, 'Cumbre Vieja');
  const cumbreViejaSo2 = cumbreViejaData.value;
  const cumbreViejaPixels = cumbreViejaData.pixels;

  // Get SO2 for Funchal
  const funchalData = await getSo2Concentration(funchal, 'Funchal');
  const funchalSo2 = funchalData.value;
  const funchalPixels = funchalData.pixels;

  // 3. Validation & Final Answer
  console.log(`Cumbre Vieja SO2 (mol/m^2): ${cumbreViejaSo2 !== null ? cumbreViejaSo2.toFixed(10) : 'N/A'}, Pixels: ${cumbreViejaPixels}`);
  console.log(`Funchal SO2 (mol/m^2): ${funchalSo2 !== null ? funchalSo2.toFixed(10) : 'N/A'}, Pixels: ${funchalPixels}`);

  if (cumbreViejaPixels === 0 || funchalPixels === 0) {
    console.log("C2");
    return;
  }

  if (cumbreViejaSo2 === null || isNaN(cumbreViejaSo2) || funchalSo2 === null || isNaN(funchalSo2)) {
    console.log("C3");
    return;
  }

  if (cumbreViejaSo2 > funchalSo2) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
